// spec: .qa/e2e/specs/admin-rooms.md 1.1 · тикет #ac28e6 (AC 11; реджект r9 «הסרת הודעה מדיווח במסך החדר — אין משוב והמסך לא מתעדכן»)
// Три роли (пишется вручную, не генератором): user2 пишет «QA-AUTO ac28e6 …» в «QA-AUTO room 29.10» → reg2 жалуется на сообщение →
// admin на странице комнаты в «דיווחים מהחדר» удаляет сообщение: «ביטול», затем подтверждение → «ההודעה הוסרה», кнопка исчезла,
// счётчики «N הודעות» −1 без обновления; в «פעילות בדיווח» — «ההודעה הוסרה על ידי מנהל/ת»; жалоба закрывается «דחיית דיווח».
// @data: сообщение удаляется самим тестом, жалоба закрывается. Если тест оборвался раньше — user2 удаляет сообщение, жалоба закрывается в finally.
// ВНИМАНИЕ: записан 12.11 без прохода в живом браузере (по скринам r10-ac28e6-*): селекторы списка комнат, поле отправки сообщения в комнате
// и значение target_type жалобы ('room_message') — проверить при первом /qa-regress.
import { test, expect } from '@playwright/test';
import type { Page, Locator } from '@playwright/test';
import { ADMIN_URL, adminAs, appApi, closeAdmin, closeApp, iphoneAs, qaText, tapIn } from '../moderation-menu/mod-helpers';
import type { Api } from '../_shared/api';

const ROOM = { id: 'cfdfaad8-65c1-45b9-978c-27f6d0010915', name: 'QA-AUTO room 29.10' };

const h = (api: Api, extra: Record<string, string> = {}) => ({ apikey: api.apikey, Authorization: api.auth, 'Content-Type': 'application/json', ...extra });

// user2 отправляет сообщение в комнату через интерфейс; таблица и id — из перехваченного запроса приложения.
async function sendRoomMessage(user: Page, text: string): Promise<{ table: string; id: string }> {
  await user.goto(`/rooms/${ROOM.id}`);
  const box = user.getByRole('textbox').last();
  await expect(box).toBeVisible({ timeout: 30_000 }); // сплэш приложения
  await box.fill(text);
  const posted = user.waitForResponse((r) => r.request().method() === 'POST' && r.url().includes('/rest/v1/') && (r.request().postData() ?? '').includes(text));
  const send = user.getByRole('button', { name: /שליחה|שלח/ }).last();
  if (await send.count()) await tapIn(user, send);
  else await box.press('Enter');
  const res = await posted;
  expect(res.status(), `отправка сообщения в комнату: ${await res.text()}`).toBeLessThan(300);
  const table = new URL(res.url()).pathname.split('/rest/v1/')[1].split('?')[0];
  let id = '';
  try {
    const body = await res.json();
    id = String((Array.isArray(body) ? body[0] : body)?.id ?? '');
  } catch {
    // ответ без тела — ищем ниже
  }
  return { table, id };
}

async function findMessageId(api: Api, table: string, text: string): Promise<string> {
  const res = await api.page.request.get(`${api.base}/rest/v1/${table}?select=*&order=created_at.desc&limit=30`, { headers: h(api), failOnStatusCode: false });
  const rows: Record<string, unknown>[] = res.ok() ? await res.json() : [];
  const row = rows.find((r) => Object.values(r).some((v) => v === text));
  return row ? String(row.id) : '';
}

async function messageExists(api: Api, table: string, id: string): Promise<boolean> {
  const res = await api.page.request.get(`${api.base}/rest/v1/${table}?id=eq.${id}&select=*`, { headers: h(api), failOnStatusCode: false });
  const rows: Record<string, unknown>[] = res.ok() ? await res.json() : [];
  // мягкое удаление: строка может остаться с пометкой (deleted_at / removed_at / status)
  return rows.length === 1 && !Object.entries(rows[0]).some(([k, v]) => /(deleted|removed)/i.test(k) && v !== null && v !== false);
}

// Все счётчики «N הודעות» на странице комнаты (участники + сводка), по порядку.
async function messageCounters(admin: Page): Promise<number[]> {
  const texts = await admin.getByText(/^\s*\d+\s+הודעות\s*$/).allInnerTexts();
  return texts.map((t) => Number(t.match(/\d+/)![0]));
}

async function openRoom(admin: Page) {
  await admin.goto(`${ADMIN_URL}/rooms`);
  const search = admin.getByRole('searchbox').or(admin.getByPlaceholder('חיפוש')).first();
  if (await search.count()) await search.fill(ROOM.name);
  await admin.getByRole('link', { name: new RegExp(ROOM.name) }).or(admin.getByRole('row', { name: new RegExp(ROOM.name) })).first().click();
  await expect(admin.getByRole('heading', { name: ROOM.name })).toBeVisible();
  await expect(admin.getByText(/דיווחים מהחדר/)).toBeVisible();
}

// Карточка жалобы в «דיווחים מהחדר»: блок с текстом сообщения и кнопкой «דחיית הדיווח»/«פתיחה בדיווחים» рядом.
function reportCard(admin: Page, text: string): Locator {
  return admin.locator('div').filter({ hasText: text }).filter({ has: admin.getByRole('link', { name: /פתיחה בדיווחים/ }) }).last();
}

async function dismissReport(admin: Page, reportId: string) {
  await admin.goto(`${ADMIN_URL}/reports?status=open&id=${reportId}`);
  const panel = admin.getByRole('region', { name: 'הדיווח הנבחר' });
  await panel.getByRole('button', { name: 'דחיית דיווח' }).click();
  const dlg = admin.getByRole('dialog').filter({ hasText: 'לדחות את הדיווח?' });
  await dlg.getByRole('textbox', { name: 'הערה פנימית' }).fill('QA-AUTO cleanup');
  const done = admin.waitForResponse((r) => r.request().method() === 'POST' && r.url().includes('/reports'));
  await dlg.getByRole('button', { name: 'דחיית דיווח' }).click();
  expect((await done).ok(), 'server action «דחיית דיווח»').toBeTruthy();
}

test.describe('מסך ניהול חדרים — жалоба из комнаты', () => {
  test('«דיווחים מהחדר» → «הסרת ההודעה»: «ביטול» не удаляет; подтверждение → «ההודעה הוסרה», кнопка исчезла, счётчики −1, «ההודעה הוסרה על ידי מנהל/ת» в журнале, «דחיית דיווח» @desktop @data (#ac28e6)', async ({ browser }) => {
    test.setTimeout(180_000);
    const author = await iphoneAs(browser, 'user2');
    const reporter = await iphoneAs(browser, 'reg2');
    let admin: Page | undefined;
    let authorApi: Api | undefined;
    let reporterApi: Api | undefined;
    const text = qaText('ac28e6', 'room');
    let table = '';
    let msgId = '';
    let reportId = '';
    let removed = false;
    let dismissed = false;
    try {
      // 1. user2 пишет в комнате
      authorApi = await appApi(author);
      ({ table, id: msgId } = await sendRoomMessage(author, text));
      if (!msgId) msgId = await findMessageId(authorApi, table, text);
      expect(msgId, `id сообщения в ${table}`).toBeTruthy();

      // 2. reg2 жалуется (тело — как у жалобы из приложения, тип цели — сообщение в комнате)
      reporterApi = await appApi(reporter);
      const rep = await reporter.request.post(`${reporterApi.base}/rest/v1/reports?select=id,status`, {
        headers: h(reporterApi, { Prefer: 'return=representation' }),
        data: { target_type: 'room_message', target_id: msgId, reason: 'spam', details: text },
        failOnStatusCode: false,
      });
      expect(rep.status(), `жалоба на сообщение комнаты: ${await rep.text()}`).toBe(201);
      reportId = String((await rep.json())[0].id);

      // 3. admin: страница комнаты, счётчики до удаления
      admin = await adminAs(browser);
      await openRoom(admin);
      const card = reportCard(admin, text);
      await expect(card).toBeVisible();
      await expect(card).toContainText('ספאם');
      const before = await messageCounters(admin);
      expect(before.length, 'на странице комнаты есть счётчики «N הודעות»').toBeGreaterThan(0);

      // 4. «ביטול» — окно закрывается, сообщение не тронуто
      const removeBtn = card.getByRole('button', { name: 'הסרת ההודעה' });
      await removeBtn.click();
      const dlg = admin.getByRole('dialog').filter({ hasText: 'להסיר את ההודעה?' });
      await expect(dlg).toBeVisible();
      await expect(dlg.getByRole('button', { name: 'ביטול' })).toBeVisible();
      await expect(dlg.getByRole('button', { name: 'הסרת ההודעה' })).toBeVisible();
      await dlg.getByRole('button', { name: 'ביטול' }).click();
      await expect(dlg).toBeHidden();
      await expect(card.getByText('ההודעה הוסרה')).toHaveCount(0);
      await expect(removeBtn).toBeVisible();
      expect(await messageExists(authorApi, table, msgId), 'после «ביטול» сообщение на месте').toBe(true);

      // 5. Подтверждение
      await removeBtn.click();
      await expect(dlg).toBeVisible();
      const action = admin.waitForResponse((r) => r.request().method() === 'POST' && r.url().startsWith(ADMIN_URL));
      await dlg.getByRole('button', { name: 'הסרת ההודעה' }).click();
      expect((await action).ok(), 'server action удаления сообщения').toBeTruthy();
      removed = true;

      // 6. Без обновления: пометка, кнопки нет, счётчики −1 (реджект r9)
      await expect(dlg).toBeHidden();
      await expect(card.getByText('ההודעה הוסרה')).toBeVisible();
      await expect(card.getByRole('button', { name: 'הסרת ההודעה' })).toHaveCount(0);
      await expect
        .poll(async () => {
          const after = await messageCounters(admin!);
          if (after.length !== before.length) return 'число счётчиков изменилось';
          const diffs = after.map((n, i) => before[i] - n);
          if (diffs.some((d) => d < 0 || d > 1)) return `неожиданно: ${before} → ${after}`;
          return diffs.some((d) => d === 1) ? 'ok' : `не уменьшились: ${before} → ${after}`;
        }, { message: 'счётчики «N הודעות» уменьшились на 1 без обновления' })
        .toBe('ok');
      await expect.poll(() => messageExists(authorApi!, table, msgId), { message: 'сообщение снято на сервере' }).toBe(false);

      // 7. Журнал жалобы
      await card.getByRole('link', { name: /פתיחה בדיווחים/ }).click();
      await expect(admin).toHaveURL(/\/reports/);
      const activity = admin.getByText('פעילות בדיווח').locator('xpath=..');
      await expect(activity.getByText('ההודעה הוסרה על ידי מנהל/ת')).toBeVisible();
      await expect(activity.getByText(/ההודעה הוסרה על ידי מנהל\/ת/).locator('xpath=..')).toContainText(/\d{2}\.\d{2}\.\d{4}.*\d{1,2}:\d{2}|\d{1,2}:\d{2}.*\d{2}\.\d{2}\.\d{4}/);

      // 8. Уборка — закрыть жалобу
      await dismissReport(admin, reportId);
      dismissed = true;
    } finally {
      if (authorApi && table && msgId && !removed) {
        await author.request.delete(`${authorApi.base}/rest/v1/${table}?id=eq.${msgId}`, { headers: h(authorApi), failOnStatusCode: false });
      }
      if (reportId && !dismissed) {
        try {
          admin ??= await adminAs(browser);
          await dismissReport(admin, reportId);
        } catch {
          console.log(`QA-AUTO: жалоба ${reportId} не закрыта — закрыть вручную в админке (/reports)`);
        }
      }
      await closeAdmin(admin);
      await closeApp(author, 'user2');
      await closeApp(reporter, 'reg2');
    }
  });
});
